def isprogram_df():
    return pd.DataFrame(ISPROGRAM)


def progress_rows():
    """İşveren kalemlerini ana ilerleme şemasına çevirir. grp = GES (GES-1/GES-2/ORTAK, gerçek ayrım)."""
    out = []
    for it in ISPROGRAM:
        out.append({
            'id': it['poz'], 'grp': it['ges'], 'disc': it['grup'] or it['ges'],
            'name': it['ad'], 'unit': it['birim'],
            'qty': float(it['miktar']), 'up': float(it['bf']),
            'plan': 0.0, 'real': 0.0,
        })
    return out
